1	import React, { useEffect, useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	
4	// Projects feature: add a project and pick which client it is for, then list every project showing
5	// the client's NAME. Opening a project (project-open-<id>) reveals its detail: the invoices raised
6	// against it, their running total, and a form to add another. Owns its own state; talks to its own
7	// /api/projects and /api/invoices endpoints and reads /api/clients to populate the client picker.
8	// data-testid anchors follow the spec's conventions.
9	type Client = { id: number; name: string; email: string };
10	type Project = {
11	  id: number;
12	  name: string;
13	  clientId: number;
14	  clientName: string;
15	  archived: boolean;
16	};
17	type Invoice = {
18	  id: number;
19	  projectId: number;
20	  amount: number;
21	  status: string;
22	  issuedDate: string;
23	  dueDate: string;
24	};
25	type Task = { id: number; projectId: number; title: string; done: boolean };
26	
27	type LineItem = {
28	  id: number;
29	  invoiceId: number;
30	  description: string;
31	  qty: number;
32	  unitPrice: number;
33	};
34	
35	function money(amount: number): string {
36	  return `$${Number(amount).toFixed(2)}`;
37	}
38	
39	// One charge line while it is being edited on screen: the fields are held as raw strings so the
40	// inputs stay controlled and the total can recompute live as they change.
41	type EditItem = { id: number; description: string; qty: string; unitPrice: string };
42	
43	// An opened invoice's detail: the things it is charging for, listed as line items (description, how
44	// many, price each), the total worked out for you, and a form to add another line. Each line can be
45	// changed in place (save) or removed, and the total re-derives from whatever lines remain. Owns its
46	// own line-item state, scoped to the one invoice it is showing.
47	function InvoiceDetail({
48	  invoiceId,
49	  onChange,
50	  onClose,
51	}: {
52	  invoiceId: number;
53	  onChange: () => void;
54	  onClose: () => void;
55	}) {
56	  const [items, setItems] = useState<EditItem[]>([]);
57	  const [description, setDescription] = useState('');
58	  const [qty, setQty] = useState('');
59	  const [unitPrice, setUnitPrice] = useState('');
60	
61	  async function load() {
62	    const res = await fetch(`/api/invoices/${invoiceId}/line-items`);
63	    const rows: LineItem[] = await res.json();
64	    setItems(
65	      rows.map((li) => ({
66	        id: li.id,
67	        description: li.description,
68	        qty: String(li.qty),
69	        unitPrice: String(li.unitPrice),
70	      })),
71	    );
72	  }
73	
74	  useEffect(() => {
75	    void load();
76	  }, [invoiceId]);
77	
78	  function editField(id: number, field: 'description' | 'qty' | 'unitPrice', value: string) {
79	    setItems((prev) => prev.map((li) => (li.id === id ? { ...li, [field]: value } : li)));
80	  }
81	
82	  function amountOf(li: EditItem): number {
83	    const line = Number(li.qty) * Number(li.unitPrice);
84	    return Number.isFinite(line) ? line : 0;
85	  }
86	
87	  async function save(li: EditItem) {
88	    if (!li.description.trim() || li.qty.trim() === '' || li.unitPrice.trim() === '') {
89	      return;
90	    }
91	    await fetch(`/api/invoices/${invoiceId}/line-items/${li.id}/update`, {
92	      method: 'POST',
93	      headers: { 'Content-Type': 'application/json' },
94	      body: JSON.stringify({
95	        description: li.description,
96	        qty: Number(li.qty),
97	        unitPrice: Number(li.unitPrice),
98	      }),
99	    });
100	    await load();
101	    onChange();
102	  }
103	
104	  async function remove(id: number) {
105	    await fetch(`/api/invoices/${invoiceId}/line-items/${id}/remove`, { method: 'POST' });
106	    await load();
107	    onChange();
108	  }
109	
110	  async function submit(e: React.FormEvent) {
111	    e.preventDefault();
112	    if (!description.trim() || qty.trim() === '' || unitPrice.trim() === '') {
113	      return;
114	    }
115	    await fetch(`/api/invoices/${invoiceId}/line-items`, {
116	      method: 'POST',
117	      headers: { 'Content-Type': 'application/json' },
118	      body: JSON.stringify({
119	        description,
120	        qty: Number(qty),
121	        unitPrice: Number(unitPrice),
122	      }),
123	    });
124	    setDescription('');
125	    setQty('');
126	    setUnitPrice('');
127	    await load();
128	    onChange();
129	  }
130	
131	  const total = items.reduce((sum, li) => sum + amountOf(li), 0);
132	
133	  return (
134	    <section data-testid="invoice-detail">
135	      <button data-testid="invoice-detail-close" type="button" onClick={onClose}>
136	        Back to invoices
137	      </button>
138	
139	      <table data-testid="invoice-lineitems-table">
140	        <tbody>
141	          {items.map((li) => (
142	            <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
143	              <td>
144	                <input
145	                  data-testid="lineitem-description"
146	                  value={li.description}
147	                  onChange={(e) => editField(li.id, 'description', e.target.value)}
148	                />
149	              </td>
150	              <td>
151	                <input
152	                  data-testid="lineitem-qty"
153	                  value={li.qty}
154	                  onChange={(e) => editField(li.id, 'qty', e.target.value)}
155	                />
156	              </td>
157	              <td>
158	                <input
159	                  data-testid="lineitem-unitprice"
160	                  value={li.unitPrice}
161	                  onChange={(e) => editField(li.id, 'unitPrice', e.target.value)}
162	                />
163	              </td>
164	              <td data-testid="lineitem-amount">{money(amountOf(li))}</td>
165	              <td>
166	                <button
167	                  data-testid={`lineitem-save-${li.id}`}
168	                  type="button"
169	                  onClick={() => save(li)}
170	                >
171	                  Save
172	                </button>
173	                <button
174	                  data-testid={`lineitem-remove-${li.id}`}
175	                  type="button"
176	                  onClick={() => remove(li.id)}
177	                >
178	                  Remove
179	                </button>
180	              </td>
181	            </tr>
182	          ))}
183	        </tbody>
184	      </table>
185	
186	      <p data-testid="invoice-amount">{money(total)}</p>
187	
188	      <form data-testid="lineitem-form" onSubmit={submit}>
189	        <input
190	          data-testid="lineitem-form-description"
191	          placeholder="Description"
192	          value={description}
193	          onChange={(e) => setDescription(e.target.value)}
194	        />
195	        <input
196	          data-testid="lineitem-form-qty"
197	          placeholder="How many"
198	          value={qty}
199	          onChange={(e) => setQty(e.target.value)}
200	        />
201	        <input
202	          data-testid="lineitem-form-unitprice"
203	          placeholder="Price each"
204	          value={unitPrice}
205	          onChange={(e) => setUnitPrice(e.target.value)}
206	        />
207	        <button data-testid="lineitem-form-submit" type="submit">
208	          Add line item
209	        </button>
210	      </form>
211	    </section>
212	  );
213	}
