215	// A project's detail: its invoices, what they add up to, and a form to add a new invoice. Owns its
216	// own invoice state, scoped to the one project it is showing.
217	function ProjectDetail({ project }: { project: Project }) {
218	  const [invoices, setInvoices] = useState<Invoice[]>([]);
219	  const [tasks, setTasks] = useState<Task[]>([]);
220	  const [taskFilter, setTaskFilter] = useState<'ALL' | 'OPEN' | 'DONE'>('ALL');
221	  const [amount, setAmount] = useState('');
222	  const [amountError, setAmountError] = useState('');
223	  const [sortByDue, setSortByDue] = useState(false);
224	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
225	
226	  async function load() {
227	    const res = await fetch(`/api/invoices?projectId=${project.id}`);
228	    setInvoices(await res.json());
229	  }
230	
231	  async function loadTasks() {
232	    const res = await fetch(`/api/tasks?projectId=${project.id}`);
233	    setTasks(await res.json());
234	  }
235	
236	  useEffect(() => {
237	    void load();
238	    void loadTasks();
239	  }, [project.id]);
240	
241	  async function toggleTask(id: number) {
242	    await fetch(`/api/tasks/${id}/toggle`, { method: 'POST' });
243	    await loadTasks();
244	  }
245	
246	  async function submit(e: React.FormEvent) {
247	    e.preventDefault();
248	    const value = Number(amount);
249	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
250	      setAmountError('Amount must be more than zero');
251	      return;
252	    }
253	    setAmountError('');
254	    await fetch('/api/invoices', {
255	      method: 'POST',
256	      headers: { 'Content-Type': 'application/json' },
257	      body: JSON.stringify({ projectId: project.id, amount: Number(amount) }),
258	    });
259	    setAmount('');
260	    await load();
261	  }
262	
263	  async function send(id: number) {
264	    await fetch(`/api/invoices/${id}/send`, { method: 'POST' });
265	    await load();
266	  }
267	
268	  async function pay(id: number) {
269	    await fetch(`/api/invoices/${id}/pay`, { method: 'POST' });
270	    await load();
271	  }
272	
273	  const shownTasks = tasks.filter((t) =>
274	    taskFilter === 'OPEN' ? !t.done : taskFilter === 'DONE' ? t.done : true,
275	  );
276	
277	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
278	  const shownInvoices = sortByDue
279	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
280	    : invoices;
281	
282	  return (
283	    <section data-testid="project-detail">
284	      <h2 data-testid="project-detail-name">{project.name}</h2>
285	
286	      <select
287	        data-testid="task-filter"
288	        value={taskFilter}
289	        onChange={(e) => setTaskFilter(e.target.value as 'ALL' | 'OPEN' | 'DONE')}
290	      >
291	        <option value="ALL">All tasks</option>
292	        <option value="OPEN">Open</option>
293	        <option value="DONE">Done</option>
294	      </select>
295	
296	      <table data-testid="project-tasks-table">
297	        <tbody>
298	          {shownTasks.map((t) => (
299	            <tr key={t.id} data-testid={`task-row-${t.id}`}>
300	              <td data-testid="task-title">{t.title}</td>
301	              <td data-testid="task-status">{t.done ? 'DONE' : 'OPEN'}</td>
302	              <td>
303	                <button data-testid={`task-toggle-${t.id}`} onClick={() => toggleTask(t.id)}>
304	                  {t.done ? 'Reopen' : 'Tick off'}
305	                </button>
306	              </td>
307	            </tr>
308	          ))}
309	        </tbody>
310	      </table>
311	
312	      <form data-testid="invoice-form" onSubmit={submit}>
313	        <input
314	          data-testid="invoice-form-amount"
315	          placeholder="Amount"
316	          value={amount}
317	          onChange={(e) => setAmount(e.target.value)}
318	        />
319	        <button data-testid="invoice-form-submit" type="submit">
320	          Add invoice
321	        </button>
322	        {amountError && (
323	          <p data-testid="invoice-form-amount-error" role="alert">
324	            {amountError}
325	          </p>
326	        )}
327	      </form>
328	
329	      <button data-testid="invoice-sort-due" type="button" onClick={() => setSortByDue(true)}>
330	        Sort by due date
331	      </button>
332	
333	      {openInvoiceId === null ? (
334	        <>
335	          <table data-testid="project-invoices-table">
336	            <tbody>
337	              {shownInvoices.map((inv) => (
338	                <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
339	                  <td data-testid="invoice-amount">{money(inv.amount)}</td>
340	                  <td data-testid="invoice-issued">{inv.issuedDate}</td>
341	                  <td data-testid="invoice-due">{inv.dueDate}</td>
342	                  <td data-testid="invoice-status">{inv.status}</td>
343	                  <td>
344	                    <button
345	                      data-testid={`invoice-open-${inv.id}`}
346	                      onClick={() => setOpenInvoiceId(inv.id)}
347	                    >
348	                      Open
349	                    </button>
350	                    {inv.status === 'DRAFT' && (
351	                      <button data-testid={`invoice-send-${inv.id}`} onClick={() => send(inv.id)}>
352	                        Send
353	                      </button>
354	                    )}
355	                    {inv.status === 'SENT' && (
356	                      <button data-testid={`invoice-pay-${inv.id}`} onClick={() => pay(inv.id)}>
357	                        Mark paid
358	                      </button>
359	                    )}
360	                  </td>
361	                </tr>
362	              ))}
363	            </tbody>
364	          </table>
365	
366	          <p data-testid="project-invoices-total">{money(total)}</p>
367	        </>
368	      ) : (
369	        <InvoiceDetail
370	          invoiceId={openInvoiceId}
371	          onChange={load}
372	          onClose={() => setOpenInvoiceId(null)}
373	        />
374	      )}
375	    </section>
376	  );
377	}
378	
379	function ProjectsPage() {
380	  const [projects, setProjects] = useState<Project[]>([]);
381	  const [clients, setClients] = useState<Client[]>([]);
382	  const [name, setName] = useState('');
383	  const [clientId, setClientId] = useState('');
384	  const [openId, setOpenId] = useState<number | null>(null);
385	  // Archived projects are tucked away (retained, not deleted) and hidden by default; this toggle
386	  // reveals them again.
387	  const [showArchived, setShowArchived] = useState(false);
388	
389	  async function loadProjects() {
390	    const res = await fetch('/api/projects');
391	    setProjects(await res.json());
392	  }
393	
394	  async function loadClients() {
395	    const res = await fetch('/api/clients');
396	    setClients(await res.json());
397	  }
398	
399	  useEffect(() => {
400	    void loadProjects();
401	    void loadClients();
402	  }, []);
403	
404	  async function submit(e: React.FormEvent) {
405	    e.preventDefault();
406	    if (!name.trim() || !clientId) {
407	      return;
408	    }
409	    await fetch('/api/projects', {
410	      method: 'POST',
411	      headers: { 'Content-Type': 'application/json' },
412	      body: JSON.stringify({ name, clientId: Number(clientId) }),
413	    });
414	    setName('');
415	    setClientId('');
416	    await loadProjects();
417	  }
418	
419	  async function remove(id: number) {
420	    await fetch(`/api/projects/${id}/delete`, { method: 'POST' });
421	    if (openId === id) {
422	      setOpenId(null);
423	    }
424	    await loadProjects();
425	  }
426	
427	  async function archive(id: number) {
428	    await fetch(`/api/projects/${id}/archive`, { method: 'POST' });
429	    if (openId === id) {
430	      setOpenId(null);
431	    }
432	    await loadProjects();
433	  }
434	
435	  const open = projects.find((p) => p.id === openId) ?? null;
436	  const visible = showArchived ? projects : projects.filter((p) => !p.archived);
437	
438	  return (
439	    <section data-testid="projects">
440	      <form data-testid="project-form" onSubmit={submit}>
441	        <input
442	          data-testid="project-form-name"
443	          placeholder="Project name"
444	          value={name}
445	          onChange={(e) => setName(e.target.value)}
446	        />
447	        <select
448	          data-testid="project-form-client"
449	          value={clientId}
450	          onChange={(e) => setClientId(e.target.value)}
451	        >
452	          <option value="">Select a client</option>
453	          {clients.map((c) => (
454	            <option key={c.id} value={String(c.id)}>
455	              {c.name}
456	            </option>
457	          ))}
458	        </select>
459	        <button data-testid="project-form-submit" type="submit">
460	          Add project
461	        </button>
462	      </form>
463	
464	      <button
465	        data-testid="projects-show-archived"
466	        type="button"
