12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // projects references clients; drop referential integrity so both tables can be truncated
36	        // (and their identity counters restarted) regardless of FK order.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
39	        jdbc.execute("TRUNCATE TABLE line_items RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
42	        jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
43	        jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
44	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
45	    }
46	
47	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
48	    @PostMapping("/seed")
49	    @SuppressWarnings("unchecked")
50	    public void seed(@RequestBody Map<String, Object> fixture) {
51	        List<Map<String, Object>> clients =
52	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
53	        for (Map<String, Object> c : clients) {
54	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
55	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"));
56	        }
57	        List<Map<String, Object>> projects =
58	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
59	        for (Map<String, Object> p : projects) {
60	            jdbc.update("INSERT INTO projects (id, name, client_id) VALUES (?, ?, ?)",
61	                    ((Number) p.get("id")).longValue(), p.get("name"),
62	                    ((Number) p.get("clientId")).longValue());
63	        }
64	        List<Map<String, Object>> contacts =
65	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
66	        for (Map<String, Object> ct : contacts) {
67	            jdbc.update(
68	                    "INSERT INTO contacts (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
69	                    ((Number) ct.get("id")).longValue(),
70	                    ((Number) ct.get("clientId")).longValue(), ct.get("name"), ct.get("email"),
71	                    ct.get("role"));
72	        }
73	        List<Map<String, Object>> invoices =
74	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
75	        for (Map<String, Object> in : invoices) {
76	            Object status = in.get("status");
77	            Object amount = in.get("amount");
78	            Object issuedDate = in.get("issuedDate");
79	            Object dueDate = in.get("dueDate");
80	            // Insert only the columns the fixture supplies, so the table's own defaults apply when a
81	            // fixture omits them (a plain null would trip the NOT NULL columns). status defaults to
82	            // DRAFT and amount defaults to 0 — an invoice's amount is now derived from its line
83	            // items, so fixtures list lineItems rather than a single typed amount.
84	            StringBuilder cols = new StringBuilder("id, project_id, status");
85	            StringBuilder marks = new StringBuilder("?, ?, ?");
86	            List<Object> args = new java.util.ArrayList<>(List.of(
87	                    ((Number) in.get("id")).longValue(),
88	                    ((Number) in.get("projectId")).longValue(),
89	                    status == null ? "DRAFT" : status.toString()));
90	            if (amount != null) {
91	                cols.append(", amount");
92	                marks.append(", ?");
93	                args.add(((Number) amount).doubleValue());
94	            }
95	            if (issuedDate != null) {
96	                cols.append(", issued_date");
97	                marks.append(", ?");
98	                args.add(issuedDate.toString());
99	            }
100	            if (dueDate != null) {
101	                cols.append(", due_date");
102	                marks.append(", ?");
103	                args.add(dueDate.toString());
104	            }
105	            jdbc.update("INSERT INTO invoices (" + cols + ") VALUES (" + marks + ")",
106	                    args.toArray());
107	            List<Map<String, Object>> lineItems =
108	                    (List<Map<String, Object>>) in.getOrDefault("lineItems", List.of());
109	            for (Map<String, Object> li : lineItems) {
110	                jdbc.update(
111	                        "INSERT INTO line_items (id, invoice_id, description, qty, unit_price)"
112	                                + " VALUES (?, ?, ?, ?, ?)",
113	                        ((Number) li.get("id")).longValue(),
114	                        ((Number) in.get("id")).longValue(), li.get("description"),
115	                        ((Number) li.get("qty")).intValue(),
116	                        ((Number) li.get("unitPrice")).doubleValue());
117	            }
118	        }
119	        List<Map<String, Object>> tasks =
120	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
121	        for (Map<String, Object> t : tasks) {
122	            jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
123	                    ((Number) t.get("id")).longValue(),
124	                    ((Number) t.get("projectId")).longValue(), t.get("title"),
125	                    Boolean.TRUE.equals(t.get("done")));
126	        }
127	    }
